package dev.podjs.runtime;
import static org.junit.Assert.*;
import android.bluetooth.*;
import android.graphics.Bitmap;
import android.os.Bundle;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
/** Paired physical-device fixture; its UUID cannot address the public main-app listener. */
public final class WatchRssArticlePeerTest {
 private static final String UUID_VALUE="8c7535e3-b05d-42fd-b5e3-1f747e864d1b";
 private DataInputStream input;private DataOutputStream output;private int actions;
 @Test public void chunkedArticleReturnsWithSavedState()throws Exception{
  String address=InstrumentationRegistry.getArguments().getString("watchAddress");assertNotNull(address);
  BluetoothAdapter adapter=InstrumentationRegistry.getInstrumentation().getTargetContext().getSystemService(BluetoothManager.class).getAdapter();assertNotNull(adapter);assertTrue(adapter.isEnabled());BluetoothDevice device=adapter.getRemoteDevice(address);assertEquals(BluetoothDevice.BOND_BONDED,device.getBondState());
  StringBuilder text=new StringBuilder("手机正文😀\n");Random random=new Random(37193);for(int i=0;i<240000;i++)text.append("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789".charAt(random.nextInt(62)));String content=text.toString(),contentHash=hash(content.getBytes(StandardCharsets.UTF_8));
  ByteArrayOutputStream packed=new ByteArrayOutputStream();try(java.util.zip.GZIPOutputStream gzip=new java.util.zip.GZIPOutputStream(packed)){gzip.write(new JSONObject().put("contentText",content).toString().getBytes(StandardCharsets.UTF_8));}byte[] encoded=packed.toByteArray();assertTrue(encoded.length>128*1024);String bodyHash=hash(encoded);JSONArray hashes=new JSONArray(),chunks=new JSONArray();for(int i=0;i*131072<encoded.length;i++){byte[] b=Arrays.copyOfRange(encoded,i*131072,Math.min(encoded.length,(i+1)*131072));String h=hash(b);hashes.put(h);chunks.put(new JSONObject().put("index",i).put("hash",h).put("data",Base64.getEncoder().encodeToString(b)));}
  JSONObject meta=new JSONObject().put("articleId","c83023f8b742978ea92293dc638bc9493b6a2acd45c521bdf8dc650996516da6").put("sourceDeviceId","article-peer-phone").put("url","https://watchrss.local/import-content/txt/article-peer-owned").put("title","真机分块正文").put("siteName","手机导入").put("excerpt","手机正文😀").put("contentHash",contentHash).put("importedAt",100).put("updatedAt",100).put("independentSaved",true).put("independentChangedAt",100).put("favoriteSaved",true).put("favoriteChangedAt",100).put("watchLaterSaved",true).put("watchLaterChangedAt",100).put("rssSourceUrl","watchrss://phone-imports").put("rssSourceTitle","手机导入").put("readingProgress",0.25).put("readingPositionBytes",17).put("readingPositionContentHash",contentHash).put("readingPositionChangedAt",100).put("isRead",false).put("deleted",false);
  JSONObject manifest=new JSONObject(meta.toString()).put("bodyHash",bodyHash).put("bodyByteCount",encoded.length).put("chunkSize",131072).put("chunkHashes",hashes).put("bodyAvailable",true).put("bodySyncMode","saved").put("metadataHash",hash(meta.toString().getBytes(StandardCharsets.UTF_8)));
  AtomicBoolean timedOut=new AtomicBoolean();ScheduledExecutorService watchdog=Executors.newSingleThreadScheduledExecutor();
  try(BluetoothSocket socket=device.createRfcommSocketToServiceRecord(UUID.fromString(UUID_VALUE))){watchdog.schedule(()->{timedOut.set(true);try{socket.close();}catch(Exception ignored){}},150,TimeUnit.SECONDS);socket.connect();input=new DataInputStream(socket.getInputStream());output=new DataOutputStream(socket.getOutputStream());
   write(new JSONObject().put("action","syncLibrary").put("version",14).put("phase","manifest").put("deviceId","article-peer-phone").put("supportsChunkedBodies",true).put("supportsArticleBatches",true).put("supportsChangeSequences",true).put("supportsMetadataOnlyArticles",true).put("fullSnapshot",true).put("changeSeqRange",new JSONObject().put("fromExclusive",0).put("toInclusive",11)).put("articleManifest",new JSONArray().put(manifest)));
   JSONObject requested=read();assertEquals(requested.toString(),"manifest",requested.optString("phase"));JSONArray requests=requested.getJSONArray("bodyRequests");assertEquals(1,requests.length());assertEquals("c83023f8b742978ea92293dc638bc9493b6a2acd45c521bdf8dc650996516da6",requests.getJSONObject(0).getString("articleId"));assertEquals(chunks.length(),requests.getJSONObject(0).getJSONArray("chunkIndexes").length());
   meta.put("body",new JSONObject().put("bodyHash",bodyHash).put("bodyByteCount",encoded.length).put("chunkSize",131072).put("chunkHashes",hashes).put("chunks",chunks));
   write(new JSONObject().put("action","syncLibrary").put("phase","articles").put("version",14).put("articles",new JSONArray().put(meta)).put("bodyRequests",new JSONArray().put(new JSONObject().put("articleId","c83023f8b742978ea92293dc638bc9493b6a2acd45c521bdf8dc650996516da6").put("bodyHash","").put("chunkIndexes",new JSONArray()))));
   TreeMap<Integer,byte[]> returned=new TreeMap<>();String returnHash=null;int returnBytes=0,count=1,items=0;String watchId="";
   for(int i=0;i<count;i++){JSONObject frame=read();assertEquals(frame.toString(),"complete",frame.optString("phase"));assertTrue(frame.optBoolean("success"));assertEquals(i,frame.optInt("batchIndex",0));count=frame.optInt("batchCount",1);watchId=frame.getString("deviceId");JSONArray articles=frame.getJSONArray("articles");for(int j=0;j<articles.length();j++){JSONObject a=articles.getJSONObject(j);assertEquals("c83023f8b742978ea92293dc638bc9493b6a2acd45c521bdf8dc650996516da6",a.getString("articleId"));assertTrue(a.getBoolean("independentSaved"));assertTrue(a.getBoolean("favoriteSaved"));assertTrue(a.getBoolean("watchLaterSaved"));assertEquals(0.25,a.getDouble("readingProgress"),0);assertEquals(17,a.getLong("readingPositionBytes"));JSONObject b=a.getJSONObject("body");returnHash=b.getString("bodyHash");returnBytes=b.getInt("bodyByteCount");JSONArray cs=b.getJSONArray("chunks");for(int k=0;k<cs.length();k++){JSONObject c=cs.getJSONObject(k);byte[] bytes=Base64.getDecoder().decode(c.getString("data"));assertEquals(c.getString("hash"),hash(bytes));assertNull(returned.put(c.getInt("index"),bytes));}items++;}}
   ByteArrayOutputStream roundtrip=new ByteArrayOutputStream();for(int i=0;i<returned.size();i++)roundtrip.write(returned.get(i));byte[] all=roundtrip.toByteArray();assertEquals(returnBytes,all.length);assertEquals(returnHash,hash(all));ByteArrayOutputStream unpacked=new ByteArrayOutputStream();try(java.util.zip.GZIPInputStream gzip=new java.util.zip.GZIPInputStream(new ByteArrayInputStream(all))){byte[] buffer=new byte[8192];for(int n;(n=gzip.read(buffer))!=-1;)unpacked.write(buffer,0,n);}JSONObject decoded=new JSONObject(unpacked.toString("UTF-8"));assertEquals(content,decoded.getString("contentText"));
   write(new JSONObject().put("action","ack").put("success",true).put("phase","received").put("applied",false));Thread.sleep(1500);write(new JSONObject().put("action","ack").put("success",true).put("phase","applied").put("applied",true));
   boolean closed;try{closed=input.read()==-1;}catch(IOException e){if(!timedOut.get()&&String.valueOf(e.getMessage()).contains("read return: -1"))closed=true;else throw e;}assertTrue(closed);assertFalse(timedOut.get());Bundle proof=new Bundle();proof.putString("articlePeerProof",new JSONObject().put("watchId",watchId).put("contentSha256",contentHash).put("incomingBodyBytes",encoded.length).put("incomingChunks",chunks.length()).put("returnedBodyBytes",returnBytes).put("returnedChunks",returned.size()).put("responseFrames",count).put("savedFlags",true).put("exactTextRoundtrip",true).toString());InstrumentationRegistry.getInstrumentation().sendStatus(0,proof);
  }finally{watchdog.shutdownNow();}
 }
 private JSONObject read()throws Exception{int n=input.readInt();assertTrue(n>0&&n<=2*1024*1024);byte[] b=new byte[n];input.readFully(b);return new JSONObject(new String(b,StandardCharsets.UTF_8));}
 private void write(JSONObject value)throws Exception{byte[] b=value.toString().getBytes(StandardCharsets.UTF_8);output.writeInt(b.length);output.write(b);output.flush();}
 private static String hash(byte[] b)throws Exception{StringBuilder s=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
}
